import java.util.*;

class Solution {
    public List<Integer> preorder(TreeNode root) {
        if (root == null) {
            return new ArrayList<>();
        }
        List<Integer> answer = new ArrayList<>();
        answer.add(root.val);
        answer.addAll(preorder(root.left));
        answer.addAll(preorder(root.right));
        return answer;
    }
}
